-- ============================================================
-- FinPractice:  All data is randomly generated; no real customer data.
-- ============================================================
USE master;
GO
IF DB_ID(N'FinPractice') IS NOT NULL
BEGIN
    ALTER DATABASE FinPractice SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE FinPractice;
END
GO
CREATE DATABASE FinPractice;
GO
USE FinPractice;
GO
SET NOCOUNT ON;
GO
CREATE TABLE dbo.branches (branch_id INT NOT NULL PRIMARY KEY, branch_name VARCHAR(50) NOT NULL, city VARCHAR(30) NOT NULL, country VARCHAR(20) NOT NULL);
GO
CREATE TABLE dbo.customers (customer_id INT NOT NULL PRIMARY KEY, full_name VARCHAR(60) NOT NULL, birth_date DATE NOT NULL, city VARCHAR(30) NOT NULL, segment VARCHAR(15) NOT NULL, signup_date DATE NOT NULL, email VARCHAR(80) NULL, phone VARCHAR(25) NULL, branch_id INT NOT NULL REFERENCES dbo.branches(branch_id));
GO
CREATE TABLE dbo.accounts (account_id INT NOT NULL PRIMARY KEY, customer_id INT NOT NULL REFERENCES dbo.customers(customer_id), account_type VARCHAR(15) NOT NULL, opened_date DATE NOT NULL, balance DECIMAL(12,2) NOT NULL, status VARCHAR(10) NOT NULL, closed_date DATE NULL);
GO
CREATE TABLE dbo.merchants (merchant_id INT NOT NULL PRIMARY KEY, merchant_name VARCHAR(50) NOT NULL, category VARCHAR(20) NOT NULL, country VARCHAR(20) NOT NULL);
GO
CREATE TABLE dbo.transactions (txn_id INT NOT NULL PRIMARY KEY, account_id INT NOT NULL REFERENCES dbo.accounts(account_id), merchant_id INT NULL REFERENCES dbo.merchants(merchant_id), txn_date DATE NOT NULL, txn_type VARCHAR(15) NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(12) NOT NULL, channel VARCHAR(10) NOT NULL);
GO
CREATE TABLE dbo.loans (loan_id INT NOT NULL PRIMARY KEY, customer_id INT NOT NULL REFERENCES dbo.customers(customer_id), product VARCHAR(15) NOT NULL, principal DECIMAL(12,2) NOT NULL, interest_rate DECIMAL(5,2) NOT NULL, term_months INT NOT NULL, issue_date DATE NOT NULL, status VARCHAR(12) NOT NULL);
GO
CREATE TABLE dbo.loan_applications (app_id INT NOT NULL PRIMARY KEY, customer_id INT NOT NULL REFERENCES dbo.customers(customer_id), requested_amount DECIMAL(12,2) NOT NULL, app_date DATE NOT NULL, decision VARCHAR(10) NOT NULL, decision_date DATE NULL);
GO
