SELECT 'branches' AS tbl, COUNT(*) AS n FROM dbo.branches UNION ALL SELECT 'customers', COUNT(*) FROM dbo.customers UNION ALL SELECT 'accounts', COUNT(*) FROM dbo.accounts UNION ALL SELECT 'merchants', COUNT(*) FROM dbo.merchants UNION ALL SELECT 'transactions', COUNT(*) FROM dbo.transactions UNION ALL SELECT 'loans', COUNT(*) FROM dbo.loans UNION ALL SELECT 'loan_applications', COUNT(*) FROM dbo.loan_applications;
